// Nginx site management — the sites-list counterpart to the Docker page. Everything
// here is plain shell commands over the one SSH session (ls/readlink/grep/nginx/
// systemctl), nothing installed on the remote side. A site file only gets structured
// edit fields when it carries the `# Generated by SSHer` marker `renderNginxSite()`
// writes — a hand-authored multi-domain file (the real devisehr site, say) is always
// still viewable, enable/disable-able and deletable, but this tool never pretends to
// understand or rewrite a config it did not generate itself.
import { promises as fs } from 'node:fs';
import posix from 'node:path/posix';
import type { Express, Response } from 'express';
import {
  badRequestRoute,
  listDockerContainers,
  need,
  nginxSiteSteps,
  renderNginxSite,
  RE,
  run,
  runOrThrow,
  runSteps,
  str,
  type AsyncRoute,
  type SessionRequest,
} from './ops.js';
import { DOTNET_MARKER } from './dotnet.js';
import { readFile, shellQuote, type SshSession } from './ssh.js';

const SITES_AVAILABLE = '/etc/nginx/sites-available';
const SITES_ENABLED = '/etc/nginx/sites-enabled';
/** `renderNginxSite()`'s own header reads "— generated by SSHer on …", not the
 *  anchored "# Generated by SSHer" compose files use — this matches it exactly (same
 *  substring the existing Docker `destroy` step already greps sites for). */
const MARKER = 'generated by SSHer';

// ------------------------------------------------------------------ helpers

interface Site {
  name: string;
  path: string;
  enabled: boolean;
  /** Only files this tool wrote get structured fields trusted enough to re-edit. */
  managed: boolean;
  domains: string[];
  target: string;
  maxBody: string;
}

/** Best-effort extraction only — display fields for the list, and a starting point
 *  for a dropped config's "add site" form. Never trusted to round-trip a file this
 *  tool did not itself write. */
function extractFields(content: string): { domains: string[]; target: string; maxBody: string; managed: boolean } {
  const domains = [...content.matchAll(/^\s*server_name\s+([^;]+);/gm)].flatMap((m) =>
    m[1].trim().split(/\s+/),
  );
  const target = /proxy_pass\s+https?:\/\/([^;\s/]+)/.exec(content)?.[1] ?? '';
  const maxBody = /client_max_body_size\s+([^;]+);/.exec(content)?.[1]?.trim() ?? '';
  return {
    domains: [...new Set(domains)],
    target,
    maxBody,
    managed: content.includes(MARKER),
  };
}

function parseSite(name: string, enabled: boolean, content: string): Site {
  return { name, path: posix.join(SITES_AVAILABLE, name), enabled, ...extractFields(content) };
}

async function listSites(session: SshSession): Promise<Site[]> {
  // One round trip: names in sites-available, and which of them sites-enabled
  // actually resolves to (a site can be "enabled" by a stray symlink of the same
  // name pointing elsewhere — vanishingly rare, but worth getting right).
  const script = `
    for f in ${shellQuote(SITES_AVAILABLE)}/*; do
      [ -f "$f" ] || continue
      name=$(basename "$f")
      link=${shellQuote(SITES_ENABLED)}/"$name"
      if [ -L "$link" ] && [ "$(readlink -f "$link" 2>/dev/null)" = "$(readlink -f "$f")" ]; then
        echo "$name|yes"
      else
        echo "$name|no"
      fi
    done
  `;
  const out = await run(session, script);
  const rows = out.stdout
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => {
      const [name, enabled] = l.split('|');
      return { name, enabled: enabled === 'yes' };
    });

  return Promise.all(
    rows.map(async (row) => {
      const content = await readFile(session, posix.join(SITES_AVAILABLE, row.name)).catch(() => Buffer.from(''));
      return parseSite(row.name, row.enabled, content.toString('utf8'));
    }),
  );
}

/** Every `host:port` an existing site's `proxy_pass` already targets, so
 *  `/api/local-apps` can tell which running services still need one. */
function targetedPorts(sites: Site[]): Set<string> {
  return new Set(sites.map((s) => s.target).filter(Boolean));
}

/** SSHer-deployed systemd services (see the .NET deploy to follow) — read directly
 *  from the unit files rather than importing a `dotnet.ts` that does not exist yet
 *  when this module alone is loaded, and to keep the two modules decoupled. */
async function dotnetApps(session: SshSession): Promise<{ name: string; port: number }[]> {
  const script = `for f in /etc/systemd/system/*.service; do [ -f "$f" ] || continue; grep -qF ${shellQuote(DOTNET_MARKER)} "$f" && basename "$f" .service; done`;
  const out = await run(session, script);
  const names = out.stdout.split('\n').map((l) => l.trim()).filter(Boolean);
  const apps: { name: string; port: number }[] = [];
  for (const name of names) {
    const unit = await readFile(session, `/etc/systemd/system/${name}.service`).catch(() => Buffer.from(''));
    const port = Number(/--urls\s+http:\/\/127\.0\.0\.1:(\d+)/.exec(unit.toString('utf8'))?.[1]);
    if (port) apps.push({ name, port });
  }
  return apps;
}

// ------------------------------------------------------------------- routes

export function registerNginx(
  app: Express,
  requireSession: import('express').RequestHandler,
  asyncRoute: AsyncRoute,
  upload: { single(field: string): import('express').RequestHandler },
): void {
  const route = (handler: (req: SessionRequest, res: Response) => Promise<void>) => badRequestRoute(asyncRoute, handler);

  app.get(
    '/api/nginx/sites',
    requireSession,
    route(async (req, res) => {
      res.json({ sites: await listSites(req.session!) });
    }),
  );

  /** Everything bound to 127.0.0.1 with a port but no nginx site pointed at it yet —
   *  Docker containers and SSHer-deployed .NET apps alike — so the nginx page can
   *  offer "add a site for this" instead of the user hunting down the port by hand. */
  app.get(
    '/api/local-apps',
    requireSession,
    route(async (req, res) => {
      const session = req.session!;
      const [sites, docker, dotnet] = await Promise.all([
        listSites(session),
        listDockerContainers(session).catch(() => ({ available: false, containers: [] as Awaited<ReturnType<typeof listDockerContainers>>['containers'] })),
        dotnetApps(session).catch(() => []),
      ]);
      const covered = targetedPorts(sites);

      const apps: { name: string; kind: 'docker' | 'dotnet'; target: string }[] = [];
      for (const c of docker.containers ?? []) {
        for (const p of c.ports) {
          if (!p.hostPort || p.hostIp !== '127.0.0.1') continue;
          const target = `127.0.0.1:${p.hostPort}`;
          if (!covered.has(target)) apps.push({ name: c.compose?.project ?? c.name, kind: 'docker', target });
        }
      }
      for (const d of dotnet) {
        const target = `127.0.0.1:${d.port}`;
        if (!covered.has(target)) apps.push({ name: d.name, kind: 'dotnet', target });
      }
      // One card per app even if several ports qualified.
      const seen = new Set<string>();
      res.json({ apps: apps.filter((a) => (seen.has(a.name) ? false : (seen.add(a.name), true))) });
    }),
  );

  /** A dropped site/`.conf` file: read locally (it is not on the server yet — nothing
   *  is written until the wizard confirms it and it passes `nginx -t`), and handed
   *  back as a pre-filled spec, the same "drop → inspect → confirm → write" shape as
   *  the Docker page's dropped-tarball flow. */
  app.post(
    '/api/nginx/upload-site',
    requireSession,
    upload.single('site'),
    route(async (req, res) => {
      const file = req.file;
      need(file, 'no file uploaded');
      try {
        const content = await fs.readFile(file.path, 'utf8');
        const fields = extractFields(content);
        const suggestedName = str(req.body?.filename)
          .replace(/\.[^.]+$/, '')
          .toLowerCase()
          .replace(/[^a-z0-9_-]/g, '-')
          .slice(0, 40);
        res.json({
          ok: true,
          suggestedName: suggestedName || 'site',
          domain: fields.domains.join(' '),
          target: fields.target,
          maxBody: fields.maxBody || '100m',
          raw: content,
        });
      } finally {
        await fs.unlink(file.path).catch(() => {});
      }
    }),
  );

  app.post(
    '/api/nginx/sites',
    requireSession,
    route(async (req, res) => {
      const session = req.session!;
      const name = str(req.body?.name);
      need(RE.name.test(name), 'Name must be lowercase letters, digits, - or _');
      const domain = str(req.body?.domain).toLowerCase();
      for (const d of domain.split(/\s+/).filter(Boolean)) need(RE.domain.test(d), `Invalid domain: ${d}`);
      need(domain, 'At least one domain is required');
      const target = str(req.body?.target);
      need(RE.hostPort.test(target), 'Target must be host:port, e.g. 127.0.0.1:3002');
      const maxBody = /^\d{1,4}[kmg]$/i.test(str(req.body?.maxBody)) ? str(req.body?.maxBody) : '100m';

      if (!req.body?.overwrite) {
        const exists = await run(session, `[ -e ${shellQuote(posix.join(SITES_AVAILABLE, name))} ] && echo yes || true`);
        need(exists.stdout.trim() !== 'yes', `${name} already exists — tick overwrite or pick another name`);
      }

      const content = renderNginxSite({ name, domain, target, maxBody });
      const { log, ok } = await runSteps(session, nginxSiteSteps(name, content));
      if (!ok) {
        res.status(500).json({ error: `${log.at(-1)!.title} failed`, log });
        return;
      }
      res.json({ ok: true, log, site: parseSite(name, true, content) });
    }),
  );

  app.post(
    '/api/nginx/sites/:name/enabled',
    requireSession,
    route(async (req, res) => {
      const session = req.session!;
      const name = str(req.params.name);
      need(RE.name.test(name), 'invalid site name');
      const available = shellQuote(posix.join(SITES_AVAILABLE, name));
      const enabled = shellQuote(posix.join(SITES_ENABLED, name));

      if (req.body?.enabled) {
        const output = await runOrThrow(
          session,
          `ln -sf ${available} ${enabled} && (nginx -t 2>&1 || { rm -f ${enabled}; echo "nginx -t failed — site disabled again" >&2; exit 1; }) && systemctl reload nginx && echo reloaded`,
        );
        res.json({ ok: true, output });
      } else {
        const output = await runOrThrow(session, `rm -f ${enabled} && systemctl reload nginx && echo reloaded`);
        res.json({ ok: true, output });
      }
    }),
  );

  app.post(
    '/api/nginx/sites/:name/delete',
    requireSession,
    route(async (req, res) => {
      const session = req.session!;
      const name = str(req.params.name);
      need(RE.name.test(name), 'invalid site name');
      const available = posix.join(SITES_AVAILABLE, name);
      const content = await readFile(session, available).catch(() => Buffer.from(''));
      need(
        content.toString('utf8').includes(MARKER),
        'Only sites SSHer created can be deleted here — edit or remove the file by hand in the File Explorer if you are sure.',
      );
      const output = await runOrThrow(
        session,
        `rm -f ${shellQuote(posix.join(SITES_ENABLED, name))} ${shellQuote(available)} && (nginx -t 2>&1; systemctl reload nginx) && echo removed`,
      );
      res.json({ ok: true, output });
    }),
  );
}
